import '@servicenow/sdk/global'
import { StringColumn, IntegerColumn } from '@servicenow/sdk/core'
import { Flow, wfa, action } from '@servicenow/sdk/automation'
import { trigger } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['flow_label_cache_simple'],
        name: 'Flow Label Cache - Simple Variables',
        description: 'Tests label cache with simple flow variables',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
        flowVariables: {
            userName: StringColumn({
                mandatory: true,
                label: 'User Name',
                max_length: 100,
            }),
            userAge: IntegerColumn({
                mandatory: true,
                label: 'User Age',
                max_length: 3,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['label_cache_simple_trigger'] },
        {
            table: 'sys_user',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_setting: 'both',
            run_when_user_list: [],
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['simple_action_step1'] },
            {
                log_message: `User: ${wfa.dataPill(params.flowVariables.userName, 'string')}, Age: ${wfa.dataPill(params.flowVariables.userAge, 'integer')}`,
                log_level: 'info',
            }
        )
    }
)
